// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }

    // fuzzed caller address; the property: owner() must be equal to the deployer (address(this)) for ANY caller
    function testFuzz_property(address caller) public {
        // keep wide domain but avoid zero-address caller to be sensible
        // do not constrain to exclude failing case for mutant
        if (caller == address(0)) caller = address(1);

        // call owner() as if from 'caller'
        bool ok;
        address observed;
        vm.prank(caller);
        try c.owner() returns (address o) {
            ok = true;
            observed = o;
        } catch {
            ok = false;
            observed = address(0);
        }

        // The reference implementation always returns the deployer (address(this)) and does not depend on caller.
        // So for all callers, owner() should succeed and equal the deployer we used in setUp (address(this)).
        assertTrue(ok && observed == address(this));
    }
}

