pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }

    // fuzzed actor will call owner(); for the correct contract owner() should always equal the deployer (address(this) from setUp),
    // but the mutant returning msg.sender will differ when called by any other address.
    function testFuzz_property(address actor) public {
        // keep actor from being the zero address to ensure meaningful distinction
        vm.assume(actor != address(0));

        // call owner() as deployer to observe baseline (should equal deployer)
        address owner_when_deployer = c.owner();

        // call owner() from fuzzed actor
        address owner_when_actor;
        vm.prank(actor);
        owner_when_actor = c.owner();

        // General rule: owner() must be invariant to caller and equal the deployer (address(this) from setUp()).
        // We assert that owner_when_actor == owner_when_deployer. The reference implementation satisfies this
        // for all actor inputs; the mutant that returns msg.sender will fail for any actor != deployer.
        assertTrue(owner_when_actor == owner_when_deployer);
    }
}

