pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }

    // fuzzed parameter: the candidate new owner address
    function testFuzz_property(address newOwner) public {
        // Keep domain wide; no assumptions so fuzzer can pick address(0)

        // Only the current owner (this) can call transferOwnership; ensure caller is owner
        // We are the owner because constructor set owner to msg.sender (this test contract)

        // Call transferOwnership and capture whether it succeeded (did not revert)
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): For any non-zero newOwner, the reference contract
        // must accept the transfer (not revert). The bug mutant removes the non-zero check
        // so it will accept address(0) too; thus there exists an input (address(0)) where
        // the mutant's behavior (succeeds) differs from the reference (reverts).
        // We assert the universal property that if newOwner != address(0) then transferOwnership
        // does not revert.
        assertTrue(newOwner == address(0) || ok);
    }
}

