// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// This test ensures only the owner (msg.sender) can transfer ownership.
// We fuzz an arbitrary caller address (as an EOA) and a newOwner address.
// We deploy a small Caller contract that will call c.transferOwnership on behalf of the EOA via a tx.origin != msg.sender scenario.

contract InvMutTest is Test {
    C c;
    Caller callerContract;

    function setUp() public {
        // per instruction: deploy c with these exact args
        c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0));
        // deploy helper that will perform an external call to c (so msg.sender = helper, tx.origin = fuzzedEOA)
        callerContract = new Caller();
    }

    // fuzzed params: an arbitrary EOA caller and a newOwner to transfer to
    function testFuzz_property(address fuzzCaller, address newOwner) public {
        vm.assume(fuzzCaller != address(0));
        vm.assume(newOwner != address(0));

        // Ensure the deployed c has owner() == address(this) as set in constructor
        address originalOwner = c.owner();
        assertEq(originalOwner, address(this));

        // We want to observe behavior when a contract (callerContract) invokes transferOwnership while the tx.origin is fuzzCaller.
        // In the reference, only msg.sender == owner (so helper != owner) -> call should fail and owner remains unchanged.
        // In the mutant, the modifier checks tx.origin which would equal fuzzCaller; if fuzzCaller == originalOwner then mutant would allow it.
        // Therefore, we drive the call with tx.origin = fuzzCaller by pratning the EOA and having it instruct the helper to call c.

        // Use vm.prank to make tx.origin and msg.sender set up: when we vm.prank(fuzzCaller), any call from test will have msg.sender = fuzzCaller and tx.origin = fuzzCaller.
        // But we want tx.origin = fuzzCaller and msg.sender = callerContract when calling c.transferOwnership, so we have the EOA instruct the helper to call c.

        // Arrange: fuzzCaller (an EOA) calls callerContract.doCall(c, newOwner)
        // Inside callerContract.doCall, it will call c.transferOwnership(newOwner). That results in tx.origin == fuzzCaller, msg.sender == address(callerContract).

        vm.prank(fuzzCaller);
        callerContract.doCall(address(c), newOwner);

        // After the call, read c.owner(). For the correct contract, transferOwnership should only succeed when msg.sender == originalOwner.
        // Here msg.sender was callerContract, not originalOwner, so the reference must keep owner unchanged.
        // The mutant that checks tx.origin may have allowed the transfer if fuzzCaller == originalOwner, making owner equal newOwner.

        // Our universal property: for ANY fuzzCaller and newOwner, if the call is invoked through an external contract (so msg.sender != tx.origin), then owner remains unchanged (transferOwnership only allowed when msg.sender == owner()).
        // We assert that c.owner() is still originalOwner. This holds for the reference for all inputs; the mutant will fail when fuzzCaller == originalOwner (it will have changed owner to newOwner).

        assertTrue(c.owner() == originalOwner);
    }
}

// Helper contract that forwards a transferOwnership call to target C.
contract Caller {
    function doCall(address target, address newOwner) external {
        // Forward the call so that msg.sender == address(this) and tx.origin is the original EOA who invoked this function
        C(target).transferOwnership(newOwner);
    }
}
